) AS d("id", "region_id", "order", "name", "description", "boss", "boss_hp_multiplier", "family_species_ids", "opponents", "time_limit_seconds", "cooldown_minutes", "ko_minutes", "money", "loot_table_id", "loot_rolls", "gem_item_id", "gem_chance", "enabled", "unlock")
-- Seulement si la région existe dans la version, et la gemme aussi.
WHERE EXISTS (SELECT 1 FROM "regions" AS r WHERE r."content_version_id" = v."id" AND r."id" = d."region_id")
  AND EXISTS (SELECT 1 FROM "items" AS i WHERE i."content_version_id" = v."id" AND i."id" = d."gem_item_id")
ON CONFLICT DO NOTHING;
